from control import *
import json,sys,time
s=r.Session();c=Controller(s)
def run(pa,render=False):
 s.reset();s.record_start();c.hold(r.INIT_Q,60)
 op=s.data.xpos[s._obj].copy();Ro=s.data.xmat[s._obj].reshape(3,3).copy()
 z=-Ro[:,0];z[2]=0;z/=np.linalg.norm(z);x=np.array([0,0,-1]);R=np.stack([x,np.cross(z,x),z],axis=1)
 p=op+Ro@np.array([pa.get('along',-.08),0,0])-R@np.array([pa.get('height',.05),pa.get('side',-.015),pa.get('depth',.14)])
 h=np.zeros(22)
 for j in [5,9,13,18]:h[j:j+4]=pa.get('pre',[.7,0,1,.7])
 h[:5]=[.6,0,0,0,0]
 c.move(p+[0,0,.13],R,h,140);c.move(p,R,h,140)
 if render:c.snap('longpre');c.contacts()
 hc=h.copy();hc[:5]=pa.get('thumb',[1.5,.3,.7,.1,.2])
 for j in [5,9,13,18]:hc[j:j+4]=pa.get('finger',[.8,0,1.2,.8])
 q=s.targets.copy()
 for t in range(140):q[7:]=h+(hc-h)*min(1,(t+1)/100);s.step(q)
 a=s.data.xpos[s._obj].copy()
 if render:c.snap('longclosed');c.contacts()
 c.move(p+[0,0,.15],R,hc,160);c.hold(s.targets,120)
 b=s.data.xpos[s._obj].copy();ph,Rh=c.pose();po=b.copy();Ro=s.data.xmat[s._obj].reshape(3,3).copy()
 print('LIFT',b-a,'obj',b,flush=True)
 if render:c.snap('longlift');c.contacts()
 if b[2]<.66:return 10+(.7-b[2]),None
 relp=Ro.T@(ph-po);relR=Ro.T@Rh;error=0
 rv=Ro[:,0]*np.pi;q=s.targets.copy()
 for t in range(240):
  u=(t+1)/240;u=u*u*(3-2*u);Rt=Rot.from_rotvec(rv*u).as_matrix()@Ro
  q=c.ik(po+Rt@relp,Rt@relR,q);q[7:]=hc;s.step(q)
  if t%60==0:print('flip',t,s.data.xpos[s._obj], 'ik',np.linalg.norm(c.k.xpos[c.pid]-(po+Rt@relp)),flush=True)
 c.hold(s.targets,100)
 ep=np.linalg.norm(s.data.xpos[s._obj]-po);er=Rot.from_matrix(s.data.xmat[s._obj].reshape(3,3)@Rt.T).magnitude()
 if render:c.snap('longflip');c.contacts()
 return ep+er*.06,s.record_stop()
if __name__=='__main__':
 pa=json.loads(sys.argv[1]) if len(sys.argv)>1 else {}
 score,A=run(pa,pa.get('render',False));print('SCORE',score,pa,flush=True)
 if A is not None:np.savez('/app/output/long'+str(pa.get('id',0))+'.npz',A=A)
