from control import *
import time,json,sys
pa=json.loads(sys.argv[1]) if len(sys.argv)>1 else {}
s=r.Session();c=Controller(s);s.record_start();A=np.load(pa.get('prefix','/app/output/branch_prefix.npz'))['actions']
for q in A:s.step(q)
m=s.model;d=mujoco.MjData(m);spec=mujoco.mjtState.mjSTATE_INTEGRATION;st=np.empty(mujoco.mj_stateSize(m,spec));rng=np.random.default_rng(121)
H=20;NA=6
# Pinch preload derived from the local grasp contact Jacobians.
delta=np.zeros(29);contacts=[];used=set();jp=np.zeros((3,m.nv));jr=jp.copy()
for co in s.data.contact:
 body=m.geom_bodyid[co.geom1];name=m.body(body).name;label='thumb' if 'thumb' in name else 'index'
 if m.geom_bodyid[co.geom2]==s._obj and ('thumb' in name or 'index' in name) and label not in used:
  used.add(label);contacts.append((body,co.pos.copy()))
v=contacts[1][1]-contacts[0][1];v/=np.linalg.norm(v)
for k,(body,pos) in enumerate(contacts):
 mujoco.mj_jac(m,s.data,jp,jr,pos,body);delta+=jp[:,s._jv].T@(v*15*(1 if k==0 else -1))/m.actuator_gainprm[s._act,0]
def controls(x,q0):
 qa=q0.copy();qb=q0.copy();qa[:7]+=x[:7]*.12;qb[:7]+=x[7:14]*.12
 qa+=delta*x[14];qb+=delta*x[14];qa[10]+=x[15]*.2;qb[10]+=x[15]*.2
 return np.clip(qa,s.lower,s.upper),np.clip(qb,s.lower,s.upper)
def evaluate(qa,qb,g):
 mujoco.mj_setState(m,d,st,spec);d.ctrl[s._act]=qa;mujoco.mj_forward(m,d);mujoco.mj_step(m,d,nstep=NA*10);d.ctrl[s._act]=qb
 best=10;bt=H
 for t in range(H):
  mujoco.mj_step(m,d,nstep=10);dist=r.keypoint_distance(d.xpos[s._obj],d.xquat[s._obj],g)
  if dist<best:best=dist;bt=t+1
  if best<.0145:break
 return best,bt
for outer in range(30):
 if s.failed or s.goal_index==45:break
 mujoco.mj_getState(m,s.data,st,spec);q0=s.targets.copy();goal=s.goals[s.goal_index]
 best,bt=evaluate(q0,q0,goal);bqa=q0.copy();bqb=q0.copy();mu=np.zeros(16);cov=np.eye(16);tick=time.time()
 for gen in range(16):
  cand=rng.multivariate_normal(mu,cov,64);cand[0]=mu;scored=[]
  for x in cand:
   qa,qb=controls(x,q0);score,t=evaluate(qa,qb,goal);scored.append(score)
   if score<best:best=score;bt=t;bqa=qa.copy();bqb=qb.copy()
  elite=cand[np.argsort(scored)[:8]];mu=.2*mu+.8*elite.mean(0);cov=.35*cov+.65*(np.cov(elite,rowvar=False)+np.eye(16)*.04)
  if gen%4==0:print('SEARCH',outer,gen,'goal',s.goal_index,'best',best,'t',bt,'sec',round(time.time()-tick,1),flush=True)
  if best<.0145:break
 for q,n in [(bqa,NA),(bqb,bt)]:
  for t in range(n):
   s.step(q)
   if s.failed or s.goal_index==45:break
 print('PULSE',outer,'goal',s.goal_index,'dist',s.goal_distance(),'best',best,'steps',bt,'sec',round(time.time()-tick,1),flush=True)
 s.save_trajectory(np.array(s._recording),'/app/output/pulse_result.npz')
 if s.data.xpos[s._obj][2]<.59:break
A=s.record_stop();s.save_trajectory(A,'/app/output/pulse_result.npz');print('FINAL',s.progress(),flush=True)
PY
